"""
The Greatest Estate Developer
Final Kaggle single-file submission.
"""

from __future__ import annotations

import base64
import io
import os
import sys
import tarfile


PAYLOAD = ""

ENV_DIR = "/tmp/estate_agent"


def _bootstrap():
    if not os.path.isdir(ENV_DIR):

        os.makedirs(
            ENV_DIR,
            exist_ok=True,
        )

        data = base64.b64decode(
            PAYLOAD
        )

        with tarfile.open(
            fileobj=io.BytesIO(data),
            mode="r:gz",
        ) as tar:

            if hasattr(
                tarfile,
                "data_filter",
            ):
                tar.extractall(
                    ENV_DIR,
                    filter="data",
                )
            else:
                tar.extractall(
                    ENV_DIR
                )

    if ENV_DIR not in sys.path:
        sys.path.insert(
            0,
            ENV_DIR,
        )


_bootstrap()

from main import agent
